package com.eventos.api.entity;
import javax.persistence.*; import java.util.*;
@Entity @Table(name="admins") public class Admin { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; @Column(nullable=false,unique=true) private String email; @Column(nullable=false) private String passwordHash; @OneToMany(mappedBy="admin",cascade=CascadeType.ALL,orphanRemoval=true) private List<Event> events=new ArrayList<>(); public Long getId(){return id;} public String getName(){return name;} public String getEmail(){return email;} public String getPasswordHash(){return passwordHash;} public void setName(String v){name=v;} public void setEmail(String v){email=v.toLowerCase();} public void setPasswordHash(String v){passwordHash=v;} }
